  parts?: Array<{ type: string; text?: string; [key: string]: unknown }>;
}) {
  if (!message.parts || message.parts.length === 0) {
    return [];
  }
  return message.parts.filter((part) => part.type === 'text' || part.type === 'step-start');
}

/**
 * Extract action parts from a message
 */
